B.Jl=new A.O("planner","Appointment Book","study",0,"Mrs. Senclair's appointment book, kept under lock. Today's page: \u201c10 AM, Crumble and Crumble. Sign. Tell T. and G. afterwards, not before.\u201d",B.cu,B.I,"desk",B.j,B.c,!1,null)
